"use client";

import React from "react";
import { Grid } from "lucide-react";
import { cn } from "@/lib/utils";

export interface GridButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  label?: string;
}

export function GridButton({
  label = "Grid Pattern",
  className,
  ...props
}: GridButtonProps) {
  return (
    <button
      type="button"
      className={cn(
        "group relative overflow-hidden rounded-2xl bg-zinc-950 px-6 py-3 text-sm font-semibold text-white border border-zinc-800 shadow-md transition-all hover:border-zinc-700 select-none cursor-pointer",
        className
      )}
      {...props}
    >
      <div className="absolute inset-0 bg-[radial-gradient(#3b82f6_1px,transparent_1px)] [background-size:12px_12px] opacity-20 group-hover:opacity-60 transition-opacity duration-300" />
      <span className="relative z-10 flex items-center gap-2">
        <Grid className="h-4 w-4 text-blue-400 group-hover:rotate-90 transition-transform duration-300" />
        <span>{label}</span>
      </span>
    </button>
  );
}

export default GridButton;
